ALTER TABLE public.sites ADD COLUMN work_status text NOT NULL DEFAULT 'operational', ADD COLUMN work_stage text NOT NULL DEFAULT 'planning', ADD COLUMN progress_updated_at timestamptz;
ALTER TABLE public.sites ADD CONSTRAINT sites_work_status_valid CHECK (work_status IN ('operational','ongoing','on_hold','completed')), ADD CONSTRAINT sites_work_stage_valid CHECK (work_stage IN ('planning','manufacturing','delivery','installation','testing','handover'));
CREATE TABLE public.site_client_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES public.sites(id) ON DELETE CASCADE, client_email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(site_id,client_email), CONSTRAINT normalized_client_email CHECK (client_email = lower(trim(client_email)) AND position('@' in client_email)>1));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_client_access TO authenticated;
GRANT ALL ON public.site_client_access TO service_role;
ALTER TABLE public.site_client_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage site clients" ON public.site_client_access FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.can_read_liftpass_site(_site_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.sites s WHERE s.id=_site_id AND (s.work_status='operational' OR public.is_staff(auth.uid()) OR EXISTS (SELECT 1 FROM public.site_client_access a JOIN auth.users u ON u.id=auth.uid() WHERE a.site_id=s.id AND a.client_email=lower(u.email) AND u.email_confirmed_at IS NOT NULL))); $$;
REVOKE ALL ON FUNCTION public.can_read_liftpass_site(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_read_liftpass_site(uuid) TO anon,authenticated,service_role;
DROP POLICY "Public can view sites" ON public.sites;
CREATE POLICY "Read accessible LiftPass sites" ON public.sites FOR SELECT TO anon,authenticated USING (public.can_read_liftpass_site(id));
DROP POLICY "Public can view lifts" ON public.lifts;
CREATE POLICY "Read accessible LiftPass lifts" ON public.lifts FOR SELECT TO anon,authenticated USING (public.can_read_liftpass_site(site_id));
DROP POLICY "Public can view contracts" ON public.amc_contracts;
CREATE POLICY "Read accessible LiftPass contracts" ON public.amc_contracts FOR SELECT TO anon,authenticated USING (EXISTS (SELECT 1 FROM public.lifts l WHERE l.id=lift_id AND public.can_read_liftpass_site(l.site_id)));
CREATE OR REPLACE FUNCTION public.get_public_liftpass_issue_counts(_lift_ids uuid[]) RETURNS TABLE(lift_id uuid,issue_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT z.lift_id,SUM(GREATEST(cardinality(z.flagged_issues),(SELECT count(*) FROM public.audit_checklist_items i WHERE i.audit_zone_id=z.id AND i.status IN ('needs_attention','not_working'))))::bigint FROM public.audit_zones z JOIN public.lifts l ON l.id=z.lift_id WHERE z.lift_id=ANY(_lift_ids) AND public.can_read_liftpass_site(l.site_id) GROUP BY z.lift_id; $$;
CREATE OR REPLACE FUNCTION public.get_public_liftpass_visit_contacts(_lift_ids uuid[]) RETURNS TABLE(id uuid,lift_id uuid,visit_date date,engineer_name text,engineer_mobile text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.id,v.lift_id,v.visit_date,v.engineer_name,v.engineer_mobile FROM public.service_visits v JOIN public.lifts l ON l.id=v.lift_id WHERE v.lift_id=ANY(_lift_ids) AND v.maintenance_completed=true AND public.can_read_liftpass_site(l.site_id) ORDER BY v.visit_date DESC,v.created_at DESC; $$;
CREATE OR REPLACE FUNCTION public.stamp_site_progress() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.work_status IS DISTINCT FROM OLD.work_status OR NEW.work_stage IS DISTINCT FROM OLD.work_stage THEN NEW.progress_updated_at=now(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER stamp_site_progress BEFORE UPDATE ON public.sites FOR EACH ROW EXECUTE FUNCTION public.stamp_site_progress();